css:
body {
    font-family: Arial, sans-serif;
    margin: 20px;
    line-height: 1.6;
}
.event-details, .transaction-details {
    border: 1px solid #ddd;
    padding: 15px;
    border-radius: 8px;
    margin-bottom: 20px;
    background-color: #f9f9f9;
}
.title {
    font-size: 20px;
    font-weight: bold;
    margin-bottom: 10px;
}
.status-paid {
    background-color: green;
    color: white;
    padding: 3px 8px;
    border-radius: 5px;
    font-weight: bold;
}
.status-unpaid {
    background-color: red;
    color: white;
    padding: 3px 8px;
    border-radius: 5px;
    font-weight: bold;
}
